const inputJson = $input.first().json;
let body = inputJson.body || inputJson;

if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}

const query = String(body.query || body.message || '').trim();
const sessionId = String(body.session_id || 'anonymous');

if (!query || query.length < 1) {
  return [{
    json: {
      query: '',
      session_id: sessionId,
      start_time: Date.now(),
      is_empty: true
    }
  }];
}

return [{
  json: {
    query: query,
    query_original: query,
    session_id: sessionId,
    start_time: Date.now(),
    is_empty: false
  }
}];

// Prag de relevanță testat anterior
const RELEVANCE_THRESHOLD = 0.40; 

const items = $input.all();

// 1. Încercăm să luăm query-ul din mai multe surse pentru a preveni pierderea lui
const query = items[0]?.json?.query || 
              $('Chat Webhook').first()?.json?.chatInput || 
              $('Chat Webhook').first()?.json?.body?.query || 
              '';

const results = items[0]?.json?.results || items[0]?.json?.sourceDocuments || items;

let chunks = [];

for (const result of results) {
  const data = result.json || result;
  const score = data.score || 0;

  // Săpăm în structura "document" văzută în debug
  const doc = data.document || data; 
  const text = doc.pageContent || doc.text || '';
  const metadata = doc.metadata || {};

  if (score >= RELEVANCE_THRESHOLD) {
    chunks.push({
      text: text,
      score: score,
      // Identificăm sursa cu fallback pentru a evita "blob" sau "unknown"
      source: metadata.source_file || metadata.source || metadata.file_name || 'Document Universitate',
      chunk_id: metadata.chunk_id || ''
    });
  }
}

// 2. Sortăm după scor
chunks.sort((a, b) => b.score - a.score);

// 3. IMPORTANT: Luăm primele 6 rezultate (slice 0, 6)
// Asta rezolvă problema duplicatelor: chiar dacă primul fișier ocupă primele 2-3 locuri, 
// restul locurilor vor fi ocupate de materiile din fișierul nou.
const topChunks = chunks.slice(0, 6);

const topScore = topChunks.length > 0 ? topChunks[0].score : 0;
const hasRelevantResults = topChunks.length > 0;

// Construim contextul pentru AI
const contextStr = topChunks.map((c, i) => 
  `[Sursa ${i+1}: ${c.source} | Scor: ${(c.score * 100).toFixed(1)}%]\n${c.text}`
).join('\n\n---\n\n');

// Lista unică de surse
const sources = [...new Set(topChunks.map(c => c.source))];

return [{
  json: {
    has_relevant_results: hasRelevantResults,
    top_score: topScore,
    num_chunks_above_threshold: topChunks.length,
    context: contextStr,
    sources: sources,
    threshold_used: RELEVANCE_THRESHOLD,
    query: query // Trimitem query-ul mai departe pentru LLM
  }
}];

// BUILD THE RAG PROMPT - Improved version
// Mai puțin conservator, mai flexibil cu interpretarea contextului

const inputData = $input.first().json;

const context = inputData.context || '';
const sources = inputData.sources || [];
const query = inputData.query || inputData.query_original || '';

const systemPrompt = `You are the ULBS Academic Assistant (CHATBOT BCETD), an official AI assistant for Universitatea Lucian Blaga din Sibiu.

## YOUR ROLE
Help students by answering their questions using the information provided in [CONTEXT]. Synthesize, combine, and reformulate information when needed to give helpful answers.

## RULES

1. **USE the [CONTEXT] as your primary source of information.** Combine information from multiple chunks when relevant.

2. **BE HELPFUL, NOT OVERLY CAUTIOUS.** If the context contains information that PARTIALLY answers the question, give that information and clarify what you don't know.

3. **REFORMULATE AND SYNTHESIZE.** The student's question may not match the exact wording in the context. Find relevant information based on meaning, not exact words. For example:
   - "Ce materii am la informatica?" matches context that mentions "Materii de studiu pentru Informatica"
   - "Cand incepe anul?" matches "Calendarul academic" with start dates
   - "Cat costa scoala?" matches "Taxe de scolarizare"

4. **ONLY say "Nu am informații" when the context truly has NOTHING related to the question.** Don't refuse just because the wording differs.

5. **NEVER invent facts not in the context.** But you CAN combine, summarize, and explain information that IS there.

6. **ANSWER in the same language as the question** (Romanian or English).

7. **CITE your sources** at the end of the answer using this format: "📄 Sursa: [filename]". If multiple sources, list all.

8. **BE CONCISE but COMPLETE.** Give the relevant information from context, structured with bullet points or short paragraphs.

## FALLBACK MESSAGE
Only if the context is COMPLETELY unrelated to the question (no overlap at all), say:
"Nu am găsit informații specifice despre [topic] în documentele disponibile. Vă recomand să contactați secretariatul facultății pentru detalii suplimentare."

## CONTEXT FROM UNIVERSITY DOCUMENTS:
${context}
## END OF CONTEXT

Now answer the student's question using the context above. Be helpful and synthesize information when needed.`;

const userMessage = `Student question: ${query}`;

return [{
  json: {
    system_prompt: systemPrompt,
    user_message: userMessage,
    query: query,
    sources: sources,
    context_length: context ? context.length : 0
  }
}];

// FORMAT FINAL RESPONSE
const llmAnswer = $input.first().json.validated_answer || $input.first().json.answer || '';
const sources = $('Build RAG Prompt').first().json.sources || [];
const startTime = $('Parse Request').first().json.start_time;
const responseTime = Date.now() - startTime;
const query = $('Parse Request').first().json.query;
const topScore = $('Relevance Threshold Check').first().json.top_score;

// Format source citations
const sourceCitation = sources.length > 0 
  ? `\n\n📄 **Surse:** ${sources.join(', ')}` 
  : '';

const response = {
  answer: llmAnswer + sourceCitation,
  sources: sources,
  confidence: topScore,
  response_time_ms: responseTime
};

// Also prepare analytics payload for async logging
const analyticsPayload = {
  query_hash: require('crypto').createHash('sha256').update(query.toLowerCase().trim()).digest('hex'),
  category: $('Ethics Guardrails (Sub-Workflow)').first()?.json?.category || 'ACADEMIC',
  match_score: topScore,
  response_ms: responseTime,
  docs_matched: sources,
  was_answered: true,
  session_id: $('Parse Request').first().json.session_id,
  created_at: new Date().toISOString()
};

return [
  { json: { type: 'response', ...response } },
  { json: { type: 'analytics', ...analyticsPayload } }
];

// ANALYTICS BRANCH (Async — does not block response)
// This data goes to Member 4's PostgreSQL logging workflow
return [$input.first()];
